import sys, json, pathlib, numpy as np
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
from PIL import Image
OUT=pathlib.Path('/app/output'); ZP=.0202
class Painter:
 def __init__(self):
  self.r=Robot(); self.obs=self.r.get_obs(cameras=[]); self.pose=np.array(self.obs.meta['proprio']['now'][7:14]); self.q=self.pose[3:].copy(); self.seq=len(list((OUT/'actions').glob('*.npy'))) if (OUT/'actions').exists() else 0
 def send(self,ps,note=''):
  ps=np.array(ps); (OUT/'actions').mkdir(exist_ok=True)
  for i in range(0,len(ps),180):
   a=ps[i:i+180]; name=f'{self.seq:04d}'; np.save(OUT/'actions'/f'{name}.npy',a)
   res=self.r.submit('ee_pose',a,dt=.05,cameras=['practice_cam'],video='none',note=note)
   (OUT/'actions'/f'{name}.json').write_text(json.dumps(res.meta)); self.seq+=1; self.pose=np.array(res.meta['proprio']['now'][7:14]);print(name,len(a),'tip',self.pose[:3], 'plan',res.meta.get('plan'),flush=True)
  return res
 def move(self,xyz,speed=.07,hold=.3):
  xyz=np.array(xyz); n=max(1,int(np.ceil(np.linalg.norm(xyz-self.pose[:3])/speed/.05)))
  ps=[np.r_[p,self.q] for p in np.linspace(self.pose[:3],xyz,n+1)[1:]];ps += [np.r_[xyz,self.q]]*int(hold/.05)
  return self.send(ps,'travel')
 def path(self,xyz,speed=.005,hold=0):
  ps=[];prev=self.pose[:3]
  for p in xyz:
   p=np.array(p);n=max(1,int(np.ceil(np.linalg.norm(p-prev)/speed/.05)))
   ps.extend([np.r_[t,self.q] for t in np.linspace(prev,p,n+1)[1:]]);prev=p
  ps += [np.r_[prev,self.q]]*int(hold/.05)
  return self.send(ps,'brush path')
 def snap(self,name,cams=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=False):
  o=self.r.get_obs(cameras=cams,depth=depth);o.save(str(OUT/name))
  for c,a in o.last.items(): Image.fromarray(a).save(OUT/f'{name}_{c}.png')
  return o
 def dip(self):
  self.move([self.pose[0],self.pose[1],.075]);self.move([-.1,.1856,.075]);self.move([-.1,.1856,.022],speed=.03,hold=.7);self.move([-.1,.1856,.075])
 def park(self):
  self.move([self.pose[0],self.pose[1],.07]);self.move([-.3,0,.07])
if __name__=='__main__' and '--replay' in sys.argv:
 r=Robot()
 for f in sorted((OUT/'actions').glob('*.npy')):r.submit('ee_pose',np.load(f),dt=.05,video='none',cameras=[])
